##### Getting started / Preview

## How to Add Preview for Markup Mode

### Add a Preview component

You can create your own component or use the component `YfmStaticView` that [provides the editor bundle](https://github.com/gravity-ui/markdown-editor/blob/main/src/view/components/YfmHtml/YfmStaticView.tsx)

### Add a handler for re-renders

```ts
const {plugins, getValue, allowHTML, breaks, linkify, linkifyTlds, needToSanitizeHtml} = props;
const [html, setHtml] = useState('');
const [meta, setMeta] = useState<object | undefined>({});
const divRef = useRef<HTMLDivElement>(null);

const theme = useThemeValue();

const render = useMemo(
    () =>
        debounce(() => {
            const res = transform(getValue(), {
                allowHTML,
                breaks,
                plugins,
                linkify,
                linkifyTlds,
                needToSanitizeHtml,
            }).result;
            setHtml(res.html);
            setMeta(res.meta);
        }, 200),
        [getValue, allowHTML, breaks, plugins, linkify, linkifyTlds, needToSanitizeHtml, theme],
    );

    useEffect(() => {
        render();
    }, [props, render]);

    return (
        <YfmStaticView
            ref={divRef}
            html={html}
            noListReset
            className="demo-preview"
        />
    );
};
```
### Pass additional properties to useMarkdownEditor

```ts
// ...
const renderPreview = useCallback<RenderPreview>(
    ({getValue}) => (
        <SplitModePreview
            getValue={getValue}
        />
    ),
    [],
);

const editor = useMarkdownEditor({allowHTML: false,
    renderPreview,
    initialEditorMode: 'wysiwyg',
    initialSplitModeEnabled: true,
    initialToolbarVisible: true,
    splitMode: 'horizontal',

});
// ...
```
import { type QAProps } from '@gravity-ui/uikit';
import type { ClassNameProps } from "../classname.js";
import type { ToolbarsPreset } from "../modules/toolbars/types.js";
import type { Editor } from "./Editor.js";
import { type SettingItems } from "./settings/index.js";
import type { ToolbarConfigs } from "./toolbar/types.js";
import "../styles/styles.css";
import "./MarkdownEditorView.css";
type ViewProps = {
    editor?: Editor;
    autofocus?: boolean;
    /** @default true */
    settingsVisible?: boolean | SettingItems[];
    toolbarsPreset?: ToolbarsPreset;
    stickyToolbar: boolean;
    enableSubmitInPreview?: boolean;
    hidePreviewAfterSubmit?: boolean;
};
export type MarkdownEditorViewProps = ClassNameProps & ToolbarConfigs & ViewProps & QAProps & {};
export declare const MarkdownEditorView: import("react").ForwardRefExoticComponent<ClassNameProps & ToolbarConfigs & ViewProps & QAProps & import("react").RefAttributes<HTMLDivElement>>;
export {};
import type { MarkdownEditorInstance } from "./editor-public-types.js";
import type { MarkdownEditorOptions } from "./types.js";
export type UseMarkdownEditorProps = MarkdownEditorOptions;
export declare function useMarkdownEditor(props: UseMarkdownEditorProps, deps?: React.DependencyList): MarkdownEditorInstance;

